"""Error taxonomy for :mod:`wsparse`."""

import os

from ._winapi import UNSUPPORTED_ERRORS, is_windows, last_error


class WSParseError(Exception):
    """Raised when a space-management operation cannot be carried out.

    ``kind`` classifies the failure so that callers can react differently:

    ``"unsupported"``
        The file system, the volume, or the object being addressed does not
        support the requested sparse-file operation.  Retrying on the same
        object will never help.
    ``"os"``
        The operating system rejected the operation: an I/O error, a sharing
        violation, a missing path, and so on.
    ``"badarg"``
        The caller passed an unusable argument.
    """

    KINDS = ("unsupported", "os", "badarg")

    def __init__(self, message, kind="os", path=None):
        super().__init__(message)
        self.kind = kind
        self.path = path

    def __str__(self):
        base = super().__str__()
        if self.path is None:
            return base
        return "%s: %s" % (self.path, base)

    @property
    def winerror(self):
        """The Win32 error code behind this failure, when there was one."""
        return getattr(self, "_winerror", None)


def classify_winerror(code):
    """Return ``"unsupported"`` or ``"os"`` for a Win32 error ``code``.

    The file system answers sparse-file requests it cannot honour with
    ``ERROR_INVALID_FUNCTION`` (and friends); those mean "this object or this
    volume will never support what you asked for", which is a different
    situation from a missing path or a sharing violation.
    """
    if code in UNSUPPORTED_ERRORS:
        return "unsupported"
    return "os"


def from_winerror(code, message, path=None, kind=None):
    """Build a :class:`WSParseError` out of a Win32 error ``code``."""
    if kind is None:
        kind = classify_winerror(code)
    detail = "%s (winerror %d)" % (message, code)
    error = WSParseError(detail, kind=kind, path=path)
    error._winerror = code
    return error


def from_os_error(exc, path=None, kind=None, message=None):
    """Build a :class:`WSParseError` out of an :class:`OSError`."""
    code = getattr(exc, "winerror", None)
    text = message or str(exc)
    if code:
        error = from_winerror(code, text, path=path, kind=kind)
        error.__cause__ = exc
        return error
    if kind is None:
        kind = "unsupported" if not is_windows() else "os"
    error = WSParseError(text, kind=kind, path=path)
    error.__cause__ = exc
    return error


def unsupported(message, path=None):
    """Build a ``kind="unsupported"`` :class:`WSParseError`."""
    return WSParseError(message, kind="unsupported", path=path)


def bad_path(path):
    """Build a ``kind="badarg"`` error for an unusable path argument."""
    return WSParseError("path must be a string or os.PathLike, got %r" % (path,),
                        kind="badarg")


def check_path(path):
    """Normalise ``path`` to a string, rejecting unusable arguments.

    Raises ``TypeError`` -- the caller converts it to a ``badarg``
    :class:`WSParseError` -- when ``path`` is not path-like.
    """
    if not isinstance(path, (str, bytes, os.PathLike)):
        raise TypeError("path must be a string or os.PathLike, got %r" % (path,))
    value = os.fspath(path)
    if isinstance(value, bytes):
        value = os.fsdecode(value)
    return value


def winerror_of(exc):
    """Return the Win32 error code carried by ``exc``, or ``last_error()``."""
    code = getattr(exc, "winerror", None)
    if code:
        return int(code)
    return int(last_error())

"""Object handling shared by the public entry points.

Every function in :mod:`wsparse` is handed a path by the collector.  Before
anything else can happen the object behind that path has to be understood:

* a sink file can be opened and asked about its layout,
* a directory (or anything else that is not a file) can never carry the sparse
  layout, and addressing one is an ``unsupported`` situation, not a transient
  I/O failure, and
* a path that does not exist is an ``os`` failure -- the caller mistyped, or
  the file has to be created.
"""

import os

from . import _winapi as win
from .errors import (
    WSParseError,
    check_path,
    classify_winerror,
    from_winerror,
    unsupported,
)

#: Access rights needed to change a file's sparse layout.
UPDATE_ACCESS = win.GENERIC_READ | win.GENERIC_WRITE


def normalize(path):
    """Return ``path`` as a string, or raise a ``badarg`` error."""
    try:
        return check_path(path)
    except TypeError as exc:
        raise WSParseError(str(exc), kind="badarg") from exc


def describe(path):
    """Return ``(path, attributes)`` for an existing object.

    Raises a ``os`` :class:`WSParseError` when the object cannot be described.
    """
    value = normalize(path)
    attributes = win.get_file_attributes(value)
    if attributes is None:
        error = win.last_error()
        kind = "os" if classify_winerror(error) == "os" else "unsupported"
        if error in (win.ERROR_FILE_NOT_FOUND, win.ERROR_PATH_NOT_FOUND):
            kind = "os"
        raise from_winerror(error, "cannot describe the object", path=value, kind=kind)
    return value, attributes


def is_directory(attributes):
    """Return ``True`` when the attribute word describes a directory."""
    return bool(attributes & win.DIRECTORY_ATTRIBUTE)


def require_file(path):
    """Return ``(path, attributes)`` for ``path``, rejecting directories."""
    value, attributes = describe(path)
    if is_directory(attributes):
        raise unsupported(
            "a directory cannot hold the sparse layout", path=value
        )
    return value, attributes


def open_update(path, create=False):
    """Open ``path`` for read/write access and return the handle.

    The handle is shared for reading, writing and deleting so that the writer
    the collector runs in parallel can keep its own handle on the same sink.
    """
    value, _ = require_file(path) if not create else _resolve_for_create(path)
    disposition = win.OPEN_ALWAYS if create else win.OPEN_EXISTING
    handle = win.create_file(value, UPDATE_ACCESS, disposition=disposition)
    if handle is None:
        error = win.last_error()
        raise _open_error(value, error)
    attributes = win.handle_attributes(handle)
    if attributes is not None and is_directory(attributes):
        # Only possible when the object was addressed through a name that also
        # resolves to a directory; a sink never is one.
        win.close_handle(handle)
        raise unsupported("a directory cannot hold the sparse layout", path=value)
    return value, handle


def open_metadata(path):
    """Open ``path`` to query its layout and return ``(path, handle)``.

    No data access is requested, so the query also works while the collector's
    writer holds the sink; a read-only share is retried when the file system
    turns the metadata request down.
    """
    value, _ = require_file(path)
    handle = win.create_file(value, 0)
    if handle is None:
        error = win.last_error()
        if error != win.ERROR_ACCESS_DENIED:
            raise _open_error(value, error)
        handle = win.create_file(value, win.GENERIC_READ)
        if handle is None:
            raise _open_error(value, win.last_error())
    return value, handle


def _resolve_for_create(path):
    """Classify ``path`` when it is about to be created."""
    value = normalize(path)
    attributes = win.get_file_attributes(value)
    if attributes is None:
        error = win.last_error()
        if error not in (win.ERROR_FILE_NOT_FOUND, win.ERROR_PATH_NOT_FOUND):
            raise from_winerror(error, "cannot describe the object", path=value)
        return value, None
    if is_directory(attributes):
        raise unsupported("a directory cannot hold the sparse layout", path=value)
    return value, attributes


def _open_error(path, error):
    """Translate a ``CreateFileW`` failure into a classified error."""
    if error == win.ERROR_ACCESS_DENIED and _is_directory_path(path):
        return unsupported("a directory cannot hold the sparse layout", path=path)
    if error in (win.ERROR_FILE_NOT_FOUND, win.ERROR_PATH_NOT_FOUND):
        return from_winerror(
            error, "no such file", path=path, kind="os"
        )
    return from_winerror(error, "cannot open the file", path=path)


def _is_directory_path(path):
    attributes = win.get_file_attributes(path)
    return attributes is not None and is_directory(attributes)


def length_of(path):
    """Return the logical length of ``path`` in bytes."""
    try:
        return os.stat(path).st_size
    except OSError as exc:
        raise from_winerror(
            getattr(exc, "winerror", 0) or 0, str(exc), path=str(path), kind="os"
        ) from exc

